// CompareEffect is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareEffect(before, after foundryvalue.Optional[Effect], assigned EffectDraft) (EffectChanges, error) {
	before = foundryEffectSnapshot(before)
	after = foundryEffectSnapshot(after)
	var changes EffectChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Effect](), before, after, assigned.fieldID.IsSet(), func(item Effect) model.ID[Effect] { return item.ID })
	if err != nil {
		return EffectChanges{}, fmt.Errorf("compare Effect.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return EffectChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.Label, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldLabel.IsSet(), func(item Effect) string { return item.Label })
	if err != nil {
		return EffectChanges{}, fmt.Errorf("compare Effect.Label: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundryEffectSnapshot(snapshot foundryvalue.Optional[Effect]) foundryvalue.Optional[Effect] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Effect]{}
	}
	return foundryvalue.Set(Effect{
		ID:    item.ID,
		Label: item.Label,
	})
}

// EffectHooks declares typed normal-write callbacks. Reference a factory with hooks=Factory on the model directive. Callbacks run synchronously; do not retain draft or transaction pointers. Nil callbacks are skipped.
type EffectHooks struct {
	// Saving runs before Creating or Updating and may change assigned fields.
	Saving func(context.Context, *database.Tx, foundryvalue.Optional[Effect], *EffectDraft) error
	// Creating runs before insert mutators; omitted required fields may be supplied here.
	Creating func(context.Context, *database.Tx, *EffectDraft) error
	// Updating receives the locked stored model before the write.
	Updating func(context.Context, *database.Tx, Effect, *EffectDraft) error
	// Deleting receives the locked stored model before soft or physical deletion.
	Deleting func(context.Context, *database.Tx, Effect) error
	// Restoring receives the locked stored model before its special lifecycle write.
	Restoring func(context.Context, *database.Tx, Effect) error
	// ForceDeleting receives the locked stored model before its special lifecycle write.
	ForceDeleting func(context.Context, *database.Tx, Effect) error
	// Created runs after SQL inside the transaction; returning an error rolls back the write.
	Created func(context.Context, *database.Tx, EffectChanges) error
	// Updated runs after SQL inside the transaction; returning an error rolls back the write.
	Updated func(context.Context, *database.Tx, EffectChanges) error
	// Deleted runs after SQL inside the transaction; returning an error rolls back the write.
	Deleted func(context.Context, *database.Tx, EffectChanges) error
	// Saved runs after SQL inside the transaction; returning an error rolls back the write.
	Saved func(context.Context, *database.Tx, EffectChanges) error
	// Restored runs after SQL inside the transaction; returning an error rolls back the write.
	Restored func(context.Context, *database.Tx, EffectChanges) error
	// ForceDeleted runs after SQL inside the transaction; returning an error rolls back the write.
	ForceDeleted func(context.Context, *database.Tx, EffectChanges) error
	// AfterCommit runs only after the outer transaction commits. Failures cannot roll back committed data; this callback is not crash durable.
	AfterCommit func(context.Context, lifecycle.Operation, EffectChanges) error
}

// EffectObserver retains this model's concrete hook factory type. Names are unique within the selected database.
type EffectObserver = lifecycle.Observer[Effect, EffectHooks]

// NewEffectObserver declares a reusable typed observer identifier without registering or constructing hooks.
func NewEffectObserver(observer string) EffectObserver {
	return lifecycle.NewObserver[Effect, EffectHooks](observer)
}

// RegisterEffectObserver binds dependency construction to a database module. Its returned factory runs once per normal write; reads and set-based writes skip it.
func RegisterEffectObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer EffectObserver, construct func(foundation.Resolver) (func() EffectHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (EffectHooks) foundryWriteHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.WriteHooks[Effect], error) {
	factories, err := lifecycle.ObserverFactories[Effect, EffectHooks](observerSet)
	if err != nil {
		return foundryquery.WriteHooks[Effect]{}, err
	}
	var allHooks []EffectHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.WriteHooks[Effect]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.WriteHooks[Effect]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.WriteHooks[Effect]{}, err
	}
	return foundryquery.WriteHooks[Effect]{
		Before: func(ctx context.Context, tx *database.Tx, operation lifecycle.Operation, before foundryvalue.Optional[Effect], mutation foundryquery.Mutation[Effect]) (foundryquery.Mutation[Effect], error) {
			values, err := foundryquery.ReadMutation(mutation)
			if err != nil {
				return foundryquery.Mutation[Effect]{}, err
			}
			var draft EffectDraft
			draft.fieldID, err = foundryquery.MutationValue[Effect, model.ID[Effect]](values, "observed_effects", "id")
			if err != nil {
				return foundryquery.Mutation[Effect]{}, err
			}
			draft.fieldLabel, err = foundryquery.MutationValue[Effect, string](values, "observed_effects", "label")
			if err != nil {
				return foundryquery.Mutation[Effect]{}, err
			}
			if err := ctx.Err(); err != nil {
				return foundryquery.Mutation[Effect]{}, err
			}
			if operation == lifecycle.Create || operation == lifecycle.Update {
				for _, hooks := range allHooks {
					if hooks.Saving != nil {
						if err := hooks.Saving(ctx, tx, before, &draft); err != nil {
							return foundryquery.Mutation[Effect]{}, err
						}
					}
					if err := ctx.Err(); err != nil {
						return foundryquery.Mutation[Effect]{}, err
					}
				}
			}
			switch operation {
			case lifecycle.Create:
				for _, hooks := range allHooks {
					if hooks.Creating != nil {
						if err := hooks.Creating(ctx, tx, &draft); err != nil {
							return foundryquery.Mutation[Effect]{}, err
						}
					}
					if err := ctx.Err(); err != nil {
						return foundryquery.Mutation[Effect]{}, err
					}
				}
			case lifecycle.Update, lifecycle.Delete, lifecycle.SoftDelete, lifecycle.Restore, lifecycle.ForceDelete:
				current, present := before.Get()
				if !present {
					return foundryquery.Mutation[Effect]{}, foundryfault.New(foundryfault.Invalid, "model hook requires a stored snapshot")
				}
				switch operation {
				case lifecycle.Update:
					for _, hooks := range allHooks {
						if hooks.Updating != nil {
							if err := hooks.Updating(ctx, tx, current, &draft); err != nil {
								return foundryquery.Mutation[Effect]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Effect]{}, err
						}
					}
				case lifecycle.Delete, lifecycle.SoftDelete:
					for _, hooks := range allHooks {
						if hooks.Deleting != nil {
							if err := hooks.Deleting(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Effect]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Effect]{}, err
						}
					}
				case lifecycle.Restore:
					for _, hooks := range allHooks {
						if hooks.Restoring != nil {
							if err := hooks.Restoring(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Effect]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Effect]{}, err
						}
					}
				case lifecycle.ForceDelete:
					for _, hooks := range allHooks {
						if hooks.ForceDeleting != nil {
							if err := hooks.ForceDeleting(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Effect]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Effect]{}, err
						}
					}
					for _, hooks := range allHooks {
						if hooks.Deleting != nil {
							if err := hooks.Deleting(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Effect]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Effect]{}, err
						}
					}
				}
			default:
				return foundryquery.Mutation[Effect]{}, foundryfault.New(foundryfault.Invalid, "invalid model hook operation")
			}
			return draft.foundryMutation(false)
		},
		After: func(ctx context.Context, tx *database.Tx, operation lifecycle.Operation, before, after foundryvalue.Optional[Effect], mutation foundryquery.Mutation[Effect]) error {
			values, err := foundryquery.ReadMutation(mutation)
			if err != nil {
				return err
			}
			var draft EffectDraft
			if values.Has("observed_effects", "id") {
				var zero model.ID[Effect]
				draft.fieldID = foundryvalue.Set(zero)
			}
			if values.Has("observed_effects", "label") {
				var zero string
				draft.fieldLabel = foundryvalue.Set(zero)
			}
			changes, err := CompareEffect(before, after, draft)
			if err != nil {
				return err
			}
			changes.operation = foundryvalue.Set(operation)
			if err := ctx.Err(); err != nil {
				return err
			}
			switch operation {
			case lifecycle.Create:
				for _, hooks := range allHooks {
					if hooks.Created != nil {
						if err := hooks.Created(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.Update:
				for _, hooks := range allHooks {
					if hooks.Updated != nil {
						if err := hooks.Updated(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.Delete:
				for _, hooks := range allHooks {
					if hooks.Deleted != nil {
						if err := hooks.Deleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.SoftDelete:
				for _, hooks := range allHooks {
					if hooks.Deleted != nil {
						if err := hooks.Deleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.Restore:
				for _, hooks := range allHooks {
					if hooks.Restored != nil {
						if err := hooks.Restored(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.ForceDelete:
				for _, hooks := range allHooks {
					if hooks.Deleted != nil {
						if err := hooks.Deleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
				for _, hooks := range allHooks {
					if hooks.ForceDeleted != nil {
						if err := hooks.ForceDeleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			default:
				return foundryfault.New(foundryfault.Invalid, "invalid model hook operation")
			}
			if operation == lifecycle.Create || operation == lifecycle.Update {
				for _, hooks := range allHooks {
					if hooks.Saved != nil {
						if err := hooks.Saved(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			}
			for _, hooks := range allHooks {
				if hooks.AfterCommit != nil {
					if err := tx.AfterCommit(func(ctx context.Context) error { return hooks.AfterCommit(ctx, operation, changes) }); err != nil {
						return err
					}
				}
			}
			return nil
		}}, nil
}

// EffectRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type EffectRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Effect) error
}

// EffectRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type EffectRetrievalObserver = lifecycle.Observer[Effect, EffectRetrievalHooks]

// NewEffectRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewEffectRetrievalObserver(observer string) EffectRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Effect, EffectRetrievalHooks](observer)
}

// RegisterEffectRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterEffectRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer EffectRetrievalObserver, construct func(foundation.Resolver) (func() EffectRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (EffectRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Effect], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Effect, EffectRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Effect]{}, err
	}
	var allHooks []EffectRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Effect]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Effect]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Effect]{}, err
	}
	return foundryquery.RetrievalHooks[Effect]{Retrieved: func(ctx context.Context, executor database.Executor, item Effect) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// EffectAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type EffectAuditPolicy struct {
	_ [0]*Effect
	// ID controls the audit representation of stored observed_effects.id.
	ID record1.Disclosure
	// Label controls the audit representation of stored observed_effects.label.
	Label record1.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes EffectChanges) Audit(policy EffectAuditPolicy) (record1.Model[Effect, model.ID[Effect]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record1.Model[Effect, model.ID[Effect]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record1.Model[Effect, model.ID[Effect]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record1.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record1.Model[Effect, model.ID[Effect]]{}, err
	}
	var captured record1.Field[Effect]
	captured, err = record1.CaptureField[Effect]("id", codec.ID[Effect](), changes.fields.ID, policy.ID)
	if err != nil {
		return record1.Model[Effect, model.ID[Effect]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record1.Model[Effect, model.ID[Effect]]{}, err
	}
	captured, err = record1.CaptureField[Effect]("label", codec.String[string](), changes.fields.Label, policy.Label)
	if err != nil {
		return record1.Model[Effect, model.ID[Effect]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record1.Model[Effect, model.ID[Effect]]{}, err
	}
	return builder.Build()
}

// EffectAuditFieldSet contains typed historical fields. An omitted field differs from an absent model or SQL NULL.
type EffectAuditFieldSet struct {
	_ [0]*Effect
	// ID retains stored observed_effects.id after write mutators; read accessors do not replace audit values.
	ID foundryvalue.Optional[record1.FieldChange[model.ID[Effect]]]
	// Label retains stored observed_effects.label after write mutators; read accessors do not replace audit values.
	Label foundryvalue.Optional[record1.FieldChange[string]]
}

// EffectAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func EffectAuditFields(history record1.Model[Effect, model.ID[Effect]]) (EffectAuditFieldSet, error) {
	view, err := record1.Inspect(history)
	if err != nil {
		return EffectAuditFieldSet{}, err
	}
	var fields EffectAuditFieldSet
	fields.ID, err = record1.ReadField(view, "id", codec.ID[Effect]())
	if err != nil {
		return EffectAuditFieldSet{}, err
	}
	fields.Label, err = record1.ReadField(view, "label", codec.String[string]())
	if err != nil {
		return EffectAuditFieldSet{}, err
	}
	return fields, nil
}

// EffectAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func EffectAuditing(policy EffectAuditPolicy) record1.Declaration {
	return record1.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record1.ResolveWriter) error {
		name, err := record1.ObserverName[Effect]()
		if err != nil {
			return err
		}
		return RegisterEffectObserver(registrar, pool, NewEffectObserver(name), func(resolver foundation.Resolver) (func() EffectHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() EffectHooks {
				write := func(ctx context.Context, tx *database.Tx, changes EffectChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return EffectHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
